NS=N+[['希腊 nekroun → nekrosis','使死亡 → 变为死亡的状态'],['拉丁化形式 → 英语 necrosis','组织坏死']]
M=N+[['希腊 nekros + manteia → nekromanteia','死者 + 占卜 → 向亡者求问'],['拉丁 necromantia → 中世纪拉丁 nigromantia','后来的拼写受到 niger“黑色”和黑魔法观念影响']]
W=[E('necrosis','英 /nəˈkrəʊsɪs/；美 /neˈkroʊsɪs/','坏死〔医学〕','身体还活着，但局部组织已经失去生命。','经希腊 nekrosis“成为死亡的状态”的拉丁化形式进入英语，前接 nekroun“使死”、nekros“死的”。现代可把 necro- 与状态后缀 -osis 联系起来。',NS,'Tissue necrosis 是组织坏死。它说的是某处细胞或组织死亡，不是整个人死亡，也不是组织仅仅暂时停止工作。读报告时先抓住这个范围即可。','tissue necrosis；areas of necrosis；bone necrosis。通常作不可数名词。','damage 是广义损伤，不一定已经坏死；necrosis 明确涉及组织死亡。',('The report describes a small area of tissue necrosis.','报告描述了一小片组织坏死区域。'),('The students examined a slide showing necrosis in the tissue sample.','学生们观察了一张显示组织样本坏死的切片。'),sources=['https://www.etymonline.com/word/necrosis','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/necrosis','https://en.wiktionary.org/wiki/necrosis']),
E('necrotic','英 /neˈkrɒtɪk/；美 /neˈkrɑːtɪk/','坏死的；与坏死有关的','用来说明这块组织发生了坏死。','与 necrosis 对应的医学形容词；现代可认 necro-“死亡”与 -otic 的形容词形式。这里的“死”作用于局部组织，不是说患者已经死亡。',N+[['现代医学形容词 necrotic','与 necrosis“组织坏死”对应，表示坏死的']],'Necrotic tissue 是坏死组织，necrotic areas 是坏死区域。这个形容词在病理或医学记录中定位组织状态，不能把它当成普通的“旧了、没用了”。','necrotic tissue/cells；a necrotic area；necrotic changes。','necrosis 是现象的名词，necrotic 修饰组织等名词；infected 是受到感染的，两种状态不是同义。',('The image marks the boundary between living and necrotic tissue.','图像标出了存活组织与坏死组织之间的界限。'),('The pathologist noted necrotic changes in the sample.','病理医生记录了样本中的坏死性变化。'),sources=['https://www.collinsdictionary.com/dictionary/english/necrotic','https://www.etymonline.com/word/necrosis']),
E('necropolis','英 /neˈkrɒpəlɪs/；美 /neˈkrɑːpələs/','大型墓地；古代墓葬群','许多坟墓聚在一起，像一座“死者之城”。','希腊 nekros“死者” + polis“城”，古代曾用于亚历山大城附近墓区的名称；英语有经晚期拉丁 necropolis 借入的路线。',N+[['希腊 nekropolis','死者之城；墓区名称'],['晚期拉丁 necropolis → 英语 necropolis','大型墓地、墓葬群']],'旅游、历史或考古资料常用它描写规模较大的墓区，尤其古代墓葬群。字面有“城”，不表示那里曾是一座活人居住、后来荒废的普通城市。','an ancient necropolis；a royal necropolis；tombs in the necropolis。','cemetery 是通用墓地；necropolis 更书面，常突出规模或历史遗址性质。',('Archaeologists mapped the tombs in the ancient necropolis.','考古学家绘制了这处古代墓葬群的墓穴分布图。'),('A path leads from the ruins to the royal necropolis.','一条小路从遗址通往王室墓地。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/necropolis','https://www.etymonline.com/word/necropolis']),
E('necromancy','/ˈnekrəmænsi/','招魂术；亡灵术〔传说、奇幻〕','向亡者求问消息，或在奇幻故事里操纵亡灵。','necro- 接“死者”，-mancy 接“占卜”。历史经希腊、拉丁、古法语进入英语；中世纪一度写成 nigro-，受“黑魔法”的联想影响，后来拼写改回 necro-。',M+[['古法语 nigromancie → 中古英语 nigromancie','招魂、巫术'],['现代英语 necromancy','拼写恢复与死者词根的联系']],'原来的重点是据说能与死者沟通、借此占卜。现代游戏和小说常把范围扩成召唤或控制亡灵；解释某部作品时，应按那部作品的设定理解。','practise necromancy；the art of necromancy；a book on necromancy。','magic 是更广的魔法概念；necromancy 特别连着亡者。它不是 necrosis“组织坏死”的一种治疗或医学操作。',('In the novel, necromancy is forbidden by the city’s rulers.','在这部小说里，城中的统治者禁止亡灵术。'),('The legend describes necromancy as a way to question the dead.','这个传说把招魂术描述成向死者求问的方式。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/necromancy','https://www.etymonline.com/word/necromancy']),
E('necromancer','英 /ˈnekrəmænsə/；美 /ˈnekrəmænsər/','招魂者；亡灵法师〔传说、奇幻〕','necromancy 是术，这个词是施术的人。','现代可与 necromancy + 表人的 -er 配对。历史上的英语 nigromancer 一类形式借自古法语 nigromansere，再按 necromancy 的来源改成 necro-，不只是现代英语第一次加 -er。',M+[['古法语 nigromancie → nigromansere','巫术、招魂术 → 施术者'],['中古英语 nigromancer 一类形式 → necromancer','拼写改回 necro-，指招魂者、亡灵法师']],'在奇幻游戏里，它往往是一种角色职业，能力围绕亡灵展开。现实历史文献也会用这个词记录对某人的巫术指控，那是记录当时的信念或说法。','a powerful necromancer；the necromancer’s spell；play as a necromancer。','sorcerer 或 wizard 泛指魔法师；necromancer 的特点是与亡者、亡灵相关。',('The player chose a necromancer who could summon skeletal guards.','玩家选择了一名能够召唤骷髅守卫的亡灵法师。'),('The tale’s necromancer claims to hear the voices of the dead.','故事中的招魂者声称能听到亡者的声音。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/necromancer','https://www.etymonline.com/word/necromancer','https://en.wiktionary.org/wiki/necromancer'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C0801');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C0801');keep={w['word']for w in W};excluded={w:'按用户当前范围暂略：更细分病理、行为或尸体检验术语及罕见派生词。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT=[dict(id='C0801',meaning='死的；死者',core='necr-/necro- 直接指向死亡或死者。',image='组织失去生命形成 necrosis；死者聚居的比喻形成 necropolis；传说里向死者求问形成 necromancy。',intro='本组分医学、历史遗址和奇幻叙事三个常见阅读方向。它们共享词根，但不能把传说中的亡灵术当作医学概念。',forms='希腊 nekros；复合词常写 necro-；necrosis 与 necrotic 是名词、形容词对应。',branches=[['局部组织坏死','necrosis、necrotic'],['墓地与遗址','necropolis'],['传说与奇幻','necromancy、necromancer']],contrasts='坏死是局部组织现象，不等于整个人死亡；necropolis 是墓区，不是任何废弃城市。',practice='看到 necro- 后先问语境：是组织、墓地，还是小说里的亡灵？再根据后半判断。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/necrosis','https://www.etymonline.com/word/necropolis','https://www.etymonline.com/word/necromancy'])]
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT[0]['words'])-set(excluded)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
